components.css:
.ds-btn-primary { display: inline-flex; min-height: 52px; align-items: center; justify-content: center; gap: 10px; padding: 0 20px; border: 0; border-radius: 999px; background: #0b0b0d; color: #ffffff; font-family: Inter, ui-sans-serif, system-ui, sans-serif; font-size: 15px; font-weight: 600; cursor: pointer; box-shadow: 0 12px 26px -10px rgba(11, 11, 13, 0.45), 0 2px 6px rgba(11, 11, 13, 0.14); transition: transform 200ms cubic-bezier(0.22, 1, 0.36, 1), box-shadow 200ms cubic-bezier(0.22, 1, 0.36, 1), opacity 200ms; }
.ds-btn-primary:hover { transform: translateY(-2px); box-shadow: 0 16px 30px -10px rgba(11, 11, 13, 0.5), 0 3px 8px rgba(11, 11, 13, 0.16); }
.ds-btn-primary:active { transform: translateY(0) scale(0.99); }
.ds-btn-primary:focus-visible { outline: 2px solid #f5c542; outline-offset: 3px; border-radius: 6px; }
.ds-btn-primary:disabled { cursor: not-allowed; opacity: 0.5; }

.ds-reveal { display: grid; width: 44px; height: 44px; place-items: center; border: 0; border-radius: 10px; background: transparent; color: #656a63; cursor: pointer; transition: color 160ms cubic-bezier(0.22, 1, 0.36, 1), background 160ms cubic-bezier(0.22, 1, 0.36, 1); }
.ds-reveal:hover { background: #f0f2ec; color: #0b0b0d; }
.ds-reveal:focus-visible { outline: 2px solid #0b0b0d; outline-offset: 3px; border-radius: 6px; }
.ds-reveal:disabled { cursor: not-allowed; opacity: 0.5; }

.ds-field { display: flex; flex-direction: column; }
.ds-field-label { margin-bottom: 8px; font-family: Inter, ui-sans-serif, system-ui, sans-serif; font-size: 13px; font-weight: 600; color: #232723; }
.ds-input-shell { position: relative; display: flex; align-items: center; height: 52px; border: 1px solid #dfe3dc; border-radius: 13px; background: #ffffff; transition: border-color 180ms cubic-bezier(0.22, 1, 0.36, 1), box-shadow 180ms cubic-bezier(0.22, 1, 0.36, 1); }
.ds-input-shell > svg { position: absolute; left: 15px; color: #656a63; pointer-events: none; transition: color 180ms cubic-bezier(0.22, 1, 0.36, 1); }
.ds-input-shell:focus-within { border-color: #0b0b0d; box-shadow: 0 0 0 3px rgba(217, 249, 157, 0.6); }
.ds-input-shell:focus-within > svg { color: #0b0b0d; }
.ds-input-shell--error { border-color: #b3261e; }
.ds-input-shell--error:focus-within { border-color: #b3261e; box-shadow: 0 0 0 3px rgba(179, 38, 30, 0.16); }
.ds-input { width: 100%; height: 100%; padding: 0 52px 0 46px; border: 0; outline: none; background: transparent; color: #101212; caret-color: #0e4b3b; font-family: Inter, ui-sans-serif, system-ui, sans-serif; font-size: 15px; border-radius: 6px; }
.ds-input::placeholder { color: #656a63; }
.ds-input:disabled { cursor: not-allowed; opacity: 0.6; }

.ds-social { margin-top: 26px; }
.ds-google { display: flex; width: 100%; min-height: 48px; align-items: center; justify-content: center; gap: 10px; padding: 0 14px; border: 1px solid #dfe3dc; border-radius: 12px; background: #ffffff; color: #0b0b0d; cursor: not-allowed; font-family: Inter, ui-sans-serif, system-ui, sans-serif; font-size: 14px; font-weight: 600; transition: border-color 180ms cubic-bezier(0.22, 1, 0.36, 1), background 180ms cubic-bezier(0.22, 1, 0.36, 1); }
.ds-google:hover { border-color: #b8bdb5; background: #fbfcfa; }
.ds-google:disabled { opacity: 1; }
.ds-google:focus-visible { outline: 2px solid #0b0b0d; outline-offset: 3px; border-radius: 6px; }
.ds-soon { margin-left: auto; padding: 4px 8px; border-radius: 999px; background: #eaf3d6; color: #0e4b3b; font-size: 10px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; }
.ds-or { display: flex; align-items: center; gap: 12px; margin-top: 18px; color: #5f645f; font-size: 11.5px; letter-spacing: 0.04em; white-space: nowrap; }
.ds-or::before, .ds-or::after { content: ""; height: 1px; flex: 1; background: #dfe3dc; }

.ds-panel { max-width: 420px; margin: 0 auto; padding: 22px 20px 36px; border-radius: 0 0 24px 24px; background: #f7f8f4; color: #101212; box-shadow: 0 18px 50px -38px rgba(0, 0, 0, 0.65); }
.ds-panel-brand { display: flex; align-items: center; gap: 10px; margin-bottom: 26px; }
.ds-brand-name { font-family: Lexend, ui-sans-serif, system-ui, sans-serif; font-size: 18px; font-weight: 700; letter-spacing: -0.02em; color: #0b0b0d; }
.ds-brand-tag { padding-left: 10px; border-left: 1px solid #dfe3dc; font-family: Inter, ui-sans-serif, system-ui, sans-serif; font-size: 9.5px; font-weight: 700; letter-spacing: 0.16em; color: #0e4b3b; }
.ds-form-wrap { width: 100%; max-width: 420px; }
.ds-panel-title { margin: 0; font-family: Lexend, ui-sans-serif, system-ui, sans-serif; font-size: clamp(30px, 7vw, 38px); font-weight: 700; line-height: 1.06; letter-spacing: -0.03em; color: #0b0b0d; text-wrap: balance; }
.ds-panel-lede { max-width: 36ch; margin: 12px 0 0; font-family: Inter, ui-sans-serif, system-ui, sans-serif; font-size: 14px; line-height: 1.6; color: #5f645f; }

.ds-message { display: flex; align-items: flex-start; gap: 9px; padding: 12px 14px; border-radius: 12px; font-family: Inter, ui-sans-serif, system-ui, sans-serif; font-size: 13px; line-height: 1.5; }
.ds-message svg { flex: none; margin-top: 1px; }
.ds-message--success { border: 1px solid rgba(14, 75, 59, 0.18); background: #eaf3d6; color: #0a3d30; box-shadow: 0 10px 22px -16px rgba(10, 61, 48, 0.55); }
.ds-message--failure { border: 1px solid #f3cfca; background: #fdecea; color: #8e1d17; box-shadow: 0 10px 22px -16px rgba(145, 29, 23, 0.5); }

.ds-strength { font-family: Inter, ui-sans-serif, system-ui, sans-serif; }
.ds-strength-top { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; font-size: 12px; color: #5f645f; }
.ds-strength-label { font-weight: 700; color: #656a63; }
.ds-strength-label[data-score="1"] { color: #c2352c; }
.ds-strength-label[data-score="2"] { color: #9a6506; }
.ds-strength-label[data-score="3"] { color: #2d55c4; }
.ds-strength-label[data-score="4"] { color: #1f6f38; }
.ds-meter { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin-top: 8px; }
.ds-meter-step { height: 5px; border-radius: 999px; background: #e4e7df; transition: background 200ms cubic-bezier(0.22, 1, 0.36, 1); }
.ds-meter-active[data-score="1"] { background: #e5473b; }
.ds-meter-active[data-score="2"] { background: #f5b62e; }
.ds-meter-active[data-score="3"] { background: #3e6ff0; }
.ds-meter-active[data-score="4"] { background: #3ea55c; }
.ds-requirements { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 12px; margin: 10px 0 0; padding: 0; list-style: none; }
.ds-requirement, .ds-requirement-met { display: flex; align-items: center; gap: 5px; font-size: 11.5px; line-height: 1.35; color: #656a63; }
.ds-requirement-met { color: #1f6f38; }

.ds-rail { width: 180px; flex: none; padding-left: 24px; border-left: 1px solid #dfe3dc; }
.ds-rail-intro { margin: 0; font-family: Lexend, ui-sans-serif, system-ui, sans-serif; font-size: 15px; font-weight: 700; line-height: 1.25; letter-spacing: -0.02em; color: #0b0b0d; }
.ds-rail-steps { display: flex; flex-direction: column; gap: 16px; margin: 22px 0 0; padding: 0; list-style: none; }
.ds-rail-steps li { display: flex; align-items: flex-start; gap: 10px; font-family: Inter, ui-sans-serif, system-ui, sans-serif; font-size: 12.5px; line-height: 1.45; color: #5f645f; }
.ds-rail-dot { width: 9px; height: 9px; flex: none; margin-top: 4px; border-radius: 3px; transform: rotate(45deg); }
.ds-dot-blue { background: #3e6ff0; }
.ds-dot-green { background: #3ea55c; }
.ds-dot-yellow { background: #f5b62e; }
.ds-rail-foot { margin: 24px 0 0; padding-top: 16px; border-top: 1px solid #dfe3dc; font-family: Inter, ui-sans-serif, system-ui, sans-serif; font-size: 11.5px; line-height: 1.5; color: #5f645f; }

.ds-board { display: block; width: 100%; height: auto; background: linear-gradient(158deg, #12151c 0%, #0b0d12 74%); }
.ds-board-frame { stroke: rgba(245, 197, 66, 0.22); stroke-width: 1; }
.ds-board-brand { fill: #f7f8f4; font-family: Lexend, ui-sans-serif, system-ui, sans-serif; font-size: 15px; font-weight: 700; letter-spacing: 0.14em; }
.ds-board-caption, .ds-board-head { fill: #8b93a7; font-family: Inter, ui-sans-serif, system-ui, sans-serif; letter-spacing: 0.14em; }
.ds-board-caption { font-size: 10px; font-weight: 600; }
.ds-board-head { font-size: 10px; font-weight: 700; letter-spacing: 0.16em; }
.ds-board-rule { stroke: rgba(255, 255, 255, 0.12); stroke-width: 1; }
.ds-board-plate { fill: rgba(245, 197, 66, 0.12); }
.ds-board-rank, .ds-board-total { fill: #f5c542; font-family: Inter, ui-sans-serif, system-ui, sans-serif; font-size: 14px; font-weight: 700; font-variant-numeric: tabular-nums; }
.ds-board-team { fill: #f2f4f8; font-family: Inter, ui-sans-serif, system-ui, sans-serif; font-size: 13px; font-weight: 700; letter-spacing: 0.04em; }
.ds-board-scan { stroke: rgba(217, 249, 157, 0.32); stroke-width: 2; animation: ds-board-scan 7s cubic-bezier(0.22, 1, 0.36, 1) infinite; }
@keyframes ds-board-scan { 0%, 8% { opacity: 0; transform: translateY(0); } 14% { opacity: 1; } 72% { opacity: 0.8; } 88%, 100% { opacity: 0; transform: translateY(330px); } }
@media (prefers-reduced-motion: reduce) { .ds-board-scan { animation: none; opacity: 0.3; } }
